(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-education'] = AINOW['data/data-education'] || {};
// Contains all prompts for the 'Education' category.
const educationPrompts = [

  // --- 1. LESSON DESIGN (1-10) ---
  {"id":"edu-1","title":"90-Minute ELL-Inclusive Persuasive Writing Block","prompt":"You are a 9th-grade English teacher in a Title I high school with 28 students, half of whom are English Language Learners reading at a 5th-grade level. You need a 90-minute block lesson on persuasive writing that meets Common Core standard W.9-10.1 and is accessible to ELL students without dumbing down the content. Design the full lesson plan including: a 10-minute hook using a viral ad or current event to illustrate persuasion, a 20-minute direct instruction segment on the PEEL paragraph structure with an anchor chart, a 40-minute collaborative writing workshop with sentence stems for ELL students, a 10-minute peer review using a structured feedback protocol, and a 10-minute exit ticket that doubles as formative assessment. Include differentiation strategies for two specific student profiles: a student reading 3 grade levels below and a gifted student who finishes early.","tags":["lesson-design","ell","writing","high-school","differentiation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"edu-2","title":"5th-Grade Fractions Lesson with Manipulatives","prompt":"You are a 5th-grade math teacher at a high-poverty urban elementary school where 70% of students are below grade level in math according to last year's state assessment scores. Design a 60-minute lesson on adding fractions with unlike denominators (CCSS 5.NF.A.1) using physical fraction tiles and Desmos for students who need digital scaffolding. Structure the lesson as: 5-minute warm-up using number talks, 15-minute concrete-representational-abstract (CRA) progression starting with fraction tile manipulation, 20-minute guided practice with three tiered problem sets (on-level, approaching, extended), 15-minute partner work using a think-aloud protocol, and 5-minute exit ticket with three problems at varying difficulty. Specify which students use which materials and how you will circulate to provide targeted feedback in under 2 minutes per group.","tags":["lesson-design","math","elementary","fractions","manipulatives"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-3","title":"7th-Grade Civil War PBL Unit Kickoff","prompt":"You are a 7th-grade social studies teacher in a suburban middle school with 32 students. You are launching a 3-week Project-Based Learning unit on the causes of the Civil War aligned to NCSS standards and your state's 7th-grade history standards. Design the entry event and Week 1 plan for a PBL unit where students act as historical advisors tasked with presenting to a mock Congressional hearing on what factors made the Civil War inevitable. Include: a compelling entry event (20 minutes) using primary source images and a provocative driving question, a weekly schedule showing how direct instruction, research workshops, and team meetings fit into five 50-minute class periods, a team role structure with four defined roles and accountability checkpoints, a milestone product for the end of Week 1, and the rubric criteria for the final Congressional presentation. Include one anchor text and two digital sources students will use.","tags":["lesson-design","pbl","social-studies","middle-school","civil-war"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-4","title":"AP Chemistry Equilibrium Flipped Lesson","prompt":"You are an AP Chemistry teacher at a competitive suburban high school with 24 students preparing for the AP exam in May. You are flipped-classroom teaching Le Chatelier's Principle (AP Chemistry Big Idea 6). Write the complete plan for a flipped lesson: first, write a detailed script for a 12-minute pre-class video (include timestamps, on-screen graphic descriptions, and two embedded check questions) explaining the principle with three real-world examples including the Haber process. Then design the 50-minute in-class session that begins with a 3-question Google Form comprehension check, moves into a 25-minute Socratic seminar using a PhET simulation, and closes with a 15-minute AP free-response practice problem with peer scoring using the AP rubric. Identify the two most common student misconceptions about this topic and how you address each.","tags":["lesson-design","ap-chemistry","flipped-classroom","high-school","science"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-5","title":"Kindergarten Phonics Station Rotation","prompt":"You are a kindergarten teacher in a Title I school where 18 of your 22 students entered the year without knowing all letter sounds. It is November and you are teaching CVC word blending. Design a 45-minute station rotation model with four stations of approximately 10 minutes each: Station 1 (teacher-led small group of 4-5 struggling readers using Elkonin sound boxes), Station 2 (independent practice using Starfall on school iPads), Station 3 (partner reading with decodable readers at two different levels), and Station 4 (hands-on word-building using magnetic letters). Write the complete teacher script for Station 1, the transition signal and procedure between stations, the behavior expectation visual you will post, and one sentence explaining how you identified which students go to the teacher-led group first.","tags":["lesson-design","kindergarten","phonics","station-rotation","early-literacy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-6","title":"3-Day Shakespeare Access Sequence for 10th Grade","prompt":"You are a 10th-grade English teacher at a mid-size public high school with 30 students, including 8 students with IEPs and 5 students who are newcomer English Language Learners with fewer than 2 years in US schools. You are beginning Romeo and Juliet. Design a 3-day introductory lesson sequence (each day is 50 minutes) that builds background knowledge and lowers the access barrier before students read Act 1. Day 1 should establish historical and social context using visual primary sources and a collaborative jigsaw. Day 2 should introduce Shakespearean language through modern parallel texts and a 15-minute performance activity. Day 3 should front-load Act 1, Scene 1 using a graphic novel version alongside the original text. For each day specify the warm-up, main activity with timing, accommodation for IEP students, accommodation for newcomer ELL students, and closing formative check.","tags":["lesson-design","english","shakespeare","high-school","inclusion"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-7","title":"3rd-Grade Science Inquiry Unit: Plant Life Cycles","prompt":"You are a 3rd-grade science teacher in a rural school district where the science lab has limited supplies and no budget for consumables beyond $50 per unit. You are teaching plant life cycles aligned to NGSS standard 3-LS1-1. Design a 2-week unit (ten 40-minute class periods) that uses fast-germinating Wisconsin Fast Plants as the hands-on anchor phenomenon. Include: a unit overview table showing each day's focus, standard addressed, and materials needed; a detailed plan for Days 1 and 2 including the phenomenon launch and initial observations; a data collection journal template students will use throughout the unit; a tiered final assessment with three levels (visual diagram with labels for approaching students, written explanation for on-level, and experimental design extension for advanced students); and a family communication note explaining the plant growing activity parents may see at home.","tags":["lesson-design","science","elementary","inquiry","ngss"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-8","title":"8th-Grade Algebra I Desmos Systems of Equations Lesson","prompt":"You are an 8th-grade Algebra I teacher in a 1:1 Chromebook school with 27 students, 6 of whom have math learning disabilities with IEP goals around fluency and procedural steps. You are teaching systems of equations by graphing (CCSS 8.EE.C.8a). Design a 55-minute lesson built around the Desmos Activity Builder. Include: the exact title and setup of the Desmos activity (include 4 specific screens you would design and what each screen asks students to do), a 10-minute launch discussion using a real-world scenario about two food trucks with different pricing, a 20-minute student Desmos work session with two teacher pause-and-discuss moments at specified screens, a 15-minute whole-class debrief connecting the graphical solution to the algebraic solution, and a 10-minute exit ticket with two problems. Specify the IEP accommodation for the 6 students with learning disabilities during the Desmos activity.","tags":["lesson-design","algebra","desmos","middle-school","technology"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-9","title":"12th-Grade Economics Socratic Seminar on the Federal Reserve","prompt":"You are a 12th-grade Economics teacher at an urban public high school with 29 students. It is spring semester and students have strong foundational vocabulary. You run a weekly 30-minute Socratic Seminar on current economic events every Friday. Design a complete Socratic Seminar framework for a seminar on Federal Reserve interest rate decisions, including: the pre-seminar reading packet (specify 3 sources at different reading levels — one accessible article, one data visualization, one op-ed), an 8-question discussion progression that moves from comprehension to analysis to normative judgment, the seating and discussion protocol you use (inner/outer circle or full-group), the individual accountability tool students complete during the seminar (not just participation points), and a post-seminar writing prompt that connects the day's discussion to a specific concept from the AP Economics curriculum.","tags":["lesson-design","economics","socratic-seminar","high-school","current-events"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-10","title":"Middle School PE and Health Cross-Curricular Nutrition Unit","prompt":"You are a middle school Physical Education and Health teacher at a K-8 school in a food desert neighborhood where many students rely on school breakfast and lunch as their primary meals. You are co-planning a 5-day, 45-minute-per-day nutrition unit with the 6th-grade science teacher, connecting to life science standards on body systems. Design the unit collaboratively: specify which content each teacher owns, which two days are co-taught and how the co-teaching model works (one teach/one support, parallel teaching, or station teaching), one hands-on lab activity connecting macronutrients to cellular energy, a community connection activity where students analyze the school's own cafeteria menu using USDA MyPlate guidelines, and a final student-created product (specify format, audience, and how it is assessed using a 4-point rubric).","tags":["lesson-design","health","pe","cross-curricular","middle-school"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 2. ASSESSMENT & FEEDBACK (11-20) ---
  {"id":"edu-11","title":"9th-Grade English Analytical Essay Rubric with Calibration Protocol","prompt":"You are a 9th-grade English department chair at a public high school working to standardize essay grading across four teachers who currently give wildly inconsistent scores. Create a 6-criterion analytical essay rubric aligned to Common Core standards W.9-10.1 through W.9-10.9 that can be used for any literary analysis essay. Each criterion must have 4 performance levels (4=Exceeds, 3=Meets, 2=Approaching, 1=Beginning) with detailed behavioral descriptors that are specific enough that two different teachers would assign the same score 80% of the time. The six criteria are: thesis and argument, evidence selection and integration, analysis and commentary, organization and transitions, style and voice, and conventions. After the rubric, write a one-paragraph calibration protocol for how the department should norm-score using anchor papers. Include a note on how to weight the criteria if converting to a 100-point grade.","tags":["assessment","rubric","english","high-school","writing"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"edu-12","title":"5-Tool Formative Assessment Battery: 4th-Grade Multiplication","prompt":"You are a 4th-grade math instructional coach supporting three classroom teachers who all teach multiplication fluency (CCSS 4.NBT.B.5) in the same week. Design a formative assessment battery of 5 different check-for-understanding tools that teachers can use across the week without grading papers: Day 1 a 3-question whiteboard check with specific look-fors teachers should observe, Day 2 a partner talk protocol with a structured stem and what circulating teachers listen for, Day 3 a 4-corner opinion poll on a conceptual question with follow-up probing questions, Day 4 a Plickers-style or hand-signal multiple choice check on the most common misconception (state the misconception explicitly), Day 5 a 2-question exit ticket with a cut-score teachers use to sort students into three groups for Monday. Include the specific Monday grouping plan based on exit ticket results.","tags":["assessment","formative","math","elementary","instructional-coaching"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-13","title":"Focused Written Feedback on an AP US History DBQ Essay","prompt":"You are an 11th-grade AP US History teacher who has just finished reading a student's 800-word Document-Based Question essay on the causes of World War I. The student has strong historical knowledge but consistently fails to explicitly connect evidence to their thesis claim — they summarize documents instead of analyzing them. The student is also a perfectionist who shuts down when feedback feels like criticism. Write the complete written feedback you would give this student: open with a genuine strength that names a specific moment in the essay, then give one prioritized revision task (not five) focused on the analysis gap with a concrete example of how to revise one specific sentence from their essay, then include a model sentence that shows what strong document analysis sounds like using their own chosen evidence, and close with a forward-looking statement about how this skill will help them on the May AP exam. Keep total feedback under 200 words.\n\n[Paste the student's essay or work sample]","tags":["assessment","feedback","ap-history","writing","high-school"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-14","title":"Standards-Based Grading Conversion Plan: High School Biology","prompt":"You are a high school science department head whose principal has mandated a shift to Standards-Based Grading (SBG) starting next semester. Your department has 6 teachers, most of whom are resistant because they have used percentage-based grading for 10+ years. Design a complete SBG implementation plan for a Biology I course including: how to identify and name 8-10 power standards from the course (give examples for Biology I specifically), a 4-point proficiency scale with behavioral descriptors for each level, a retake and reassessment policy that is sustainable for teachers with 150 students each, a parent communication letter explaining the new system, and a gradebook setup guide for PowerSchool or a similar SIS. Include the three most common teacher objections to SBG and evidence-based responses to each objection.","tags":["assessment","standards-based-grading","high-school","science","department-leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-15","title":"Semester-Long Reading Portfolio Framework for 1st Grade","prompt":"You are a K-2 literacy coordinator at an elementary school that is moving away from standardized reading assessments toward portfolio-based documentation of early literacy growth. Design a semester-long reading portfolio framework for 1st grade that: specifies exactly 6 artifact types students collect (name each artifact, describe what it captures, and explain how a 6-year-old can participate in selecting it), includes a simple 3-level reading conference protocol teachers use every 3 weeks with sentence starters for prompting student self-reflection, provides a rubric teachers use to evaluate portfolio completeness and growth (not just performance level), gives families a one-page guide explaining how to understand the portfolio at the December family conference, and describes how this portfolio data connects to the school's reading intervention identification process when a student appears to be at risk.","tags":["assessment","portfolio","early-literacy","elementary","k-2"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-16","title":"Substantive Peer Review Protocol for 7th-Grade Lab Reports","prompt":"You are a 7th-grade science teacher with 30 students who just completed their first independent investigation on variables and controls. Students need to peer review each other's lab reports, but in past years peer review has devolved into students writing good job and making no substantive changes. Design a structured peer review protocol that takes exactly 20 minutes in class and produces actionable revision feedback. Include: a 4-criterion review checklist specific to lab reports (hypothesis, data table, analysis, conclusion) with 2 specific yes/no checkpoints per criterion, a sentence-stem bank of 8 specific feedback phrases students must choose from (no free-form praise allowed), a 3-minute partner discussion protocol after the written feedback where the author asks one clarifying question, a teacher monitoring checklist to assess whether peer feedback is substantive during the 20 minutes, and a post-revision self-assessment students submit with the final draft explaining what they changed based on peer feedback and why.","tags":["assessment","peer-review","science","middle-school","writing"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-17","title":"3-Day Diagnostic Assessment for Incoming 6th-Grade Math Students","prompt":"You are a 6th-grade math teacher receiving students from four different 5th-grade classrooms, each of which covered different amounts of the curriculum due to COVID learning loss. You have the first week of school to diagnose gaps before beginning your 6th-grade curriculum. Design a 3-day diagnostic assessment sequence: Day 1 is a 20-minute no-stakes written diagnostic covering the 8 most critical 5th-grade math skills (list all 8 skills with one sample problem each), Day 2 is a 15-minute number talk you observe and take notes on to assess number sense and reasoning strategies, Day 3 is a 10-minute one-on-one reading of a math word problem with 3 students per day while others do review stations. Provide a data analysis template teachers complete after Day 1 that sorts students into three tiers, specify what instruction looks like for each tier in Week 2, and explain how you communicate results to 5th-grade teachers for their own instructional reflection.","tags":["assessment","diagnostic","math","middle-school","data"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-18","title":"Student-Led Conference Preparation System: 5th Grade","prompt":"You are a 5th-grade teacher at a school that has replaced traditional parent-teacher conferences with student-led conferences. It is two weeks before conferences and your 25 students (ages 10-11) need to prepare to lead a 20-minute conference with their families. Design the complete student preparation curriculum: a 5-day, 20-minutes-per-day preparation sequence in advisory class, a portfolio selection guide that helps students choose 3 pieces showing growth (not just best work) with a reflection sentence for each, a conference script template with sentence starters that students personalize (include the opening, the portfolio share, the goal-setting section, and the closing), a one-page family guide sent home explaining what to expect and 5 questions families should ask, and a teacher observation checklist used during the actual conference to assess student communication skills. Include special guidance for students whose families do not speak English as a primary language.","tags":["assessment","student-led-conferences","elementary","family-engagement","reflection"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-19","title":"AP Biology FRQ Calibration and Reteach Process","prompt":"You are an AP Biology teacher who has received 34 student responses to a free-response question on cellular respiration and ATP synthesis. Before returning papers, you want to calibrate your scoring using the College Board rubric. Design a complete scoring calibration process: identify the 5 most common errors AP readers see on cellular respiration FRQs and how each maps to rubric point deductions, create an anchor paper set by writing brief descriptions of what a 10/10 response, a 7/10 response, a 4/10 response, and a 1/10 response each contain, write a comment bank of 8 specific written comments that correspond to the most common errors you will mark, design a post-score student analysis sheet where students identify their own error patterns and write a corrected version of their weakest response section, and outline a 20-minute reteach mini-lesson targeting the two most missed rubric points.","tags":["assessment","ap-biology","rubric","calibration","feedback"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-20","title":"Observation-Based Kindergarten Math Assessment System","prompt":"You are a kindergarten teacher in a play-based learning environment where your principal supports moving away from paper-and-pencil assessments for 5-year-olds. You need to assess 22 students on CCSS K.CC counting and cardinality standards during regular classroom routines without pulling students out for formal testing. Design an observation-based assessment system: specify 6 counting behaviors you will observe (tied to specific K.CC standards), create a class observation grid you can carry on a clipboard and mark with a simple code during morning meeting, center time, and transitions, design 3 structured play provocations (a specific math center setup) that naturally elicit the target counting behaviors, write a 1-page parent report narrative template using plain language (no education jargon) that communicates where each child is in counting development, and describe how you use this data to form small groups for math intervention 3 days per week.","tags":["assessment","kindergarten","math","authentic-assessment","early-childhood"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 3. DIFFERENTIATED INSTRUCTION (21-30) ---
  {"id":"edu-21","title":"Co-Teaching Plan for Inclusive 8th-Grade Science: Plate Tectonics","prompt":"You are an 8th-grade science teacher co-teaching with a special education teacher in an inclusive classroom of 28 students, 9 of whom have IEPs. Six of the IEP students have learning disabilities in reading, two have autism spectrum disorder, and one has an emotional behavioral disorder. You are beginning a unit on plate tectonics. Design a 2-week co-teaching plan that uses three different co-teaching models across the unit (specify which model on which days and why): parallel teaching, station teaching, and one teach/one assist. Include: the specific role each teacher plays during each model, how the seating arrangement changes between models, three specific accommodations that appear in the IEPs of students with reading LDs and how they are embedded into whole-class activities rather than pull-out modifications, a behavior support plan for the student with EBD specific to the transition between co-teaching models, and how both teachers debrief after class using a 10-minute protocol.","tags":["differentiation","co-teaching","special-ed","science","inclusion"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-22","title":"Newcomer ELL 4-Week Support Plan in 3rd-Grade Math","prompt":"You are a 3rd-grade teacher who has just received two newcomer students from Guatemala who speak Kaqchikel as their first language and have limited Spanish literacy. They have had 1 year of formal schooling. It is October and your class is deep into multiplication. Design a 4-week differentiated support plan for these two students that does not pull them out of the classroom for the entire math block. Include: a language acquisition progression for math vocabulary (provide the 15 most critical multiplication vocabulary words with visual card descriptions), two specific sheltered instruction strategies you will embed in whole-class lessons, a peer buddy system protocol including how you select and prepare the buddy, a modified weekly assignment structure that allows the newcomers to demonstrate math understanding without requiring English writing, and a family communication plan for families who may have limited literacy and no access to school translation services.","tags":["differentiation","ell","newcomer","math","elementary"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-23","title":"Semester-Long Gifted Extension Menu for 5th-Grade Readers","prompt":"You are a 5th-grade teacher with 4 students who are reading 3 or more grade levels above their peers and consistently finish class reading tasks in half the time. Your school has no gifted pull-out program, so enrichment happens entirely in your classroom. Design a semester-long independent learning menu for these students that runs parallel to the whole-class ELA curriculum without requiring extra teacher planning time. The menu should include: 5 anchor activities (always available, self-directed, take 30-60 minutes each) connected to the books and units the whole class is studying, 3 project choices for the end of each unit that go significantly deeper than the grade-level project, a student-managed tracking system showing what they have completed and what their next steps are, a brief weekly 10-minute check-in conference protocol between teacher and student, and a presentation opportunity where gifted students share a project product with a real audience (specify the audience and format). Ensure no activity is just more of the same work.","tags":["differentiation","gifted","reading","elementary","extension"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-24","title":"Dyslexia Support Within a 2nd-Grade Literacy Block","prompt":"You are a 2nd-grade teacher with a student who was recently identified with dyslexia. The student has average intelligence and strong comprehension when text is read aloud but struggles severely with decoding and phonological awareness. Design a classroom support plan that works within your 90-minute literacy block: specify the 3 evidence-based Orton-Gillingham strategies you will embed in small group instruction 4 days per week for 20 minutes, describe how you modify the independent reading rotation so the student accesses grade-level content through audiobooks on Learning Ally while also working on decoding, provide 5 specific low-embarrassment classroom accommodations that support the student without identifying them in front of peers, write a script for how you explain the student's reading approach to curious classmates if they ask, and outline what you will share with the student's family at the monthly progress meeting including the specific data you track.","tags":["differentiation","dyslexia","early-literacy","elementary","special-ed"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-25","title":"Three-Tier Primary Source Assignment: 10th-Grade World History","prompt":"You are a 10th-grade World History teacher with 31 students at three distinct readiness levels: 8 students reading below an 8th-grade level who struggle with primary source vocabulary, 17 students at grade level, and 6 students who are in the honors track and capable of college-level analysis. You are assigning a primary source analysis on the causes of World War I using 4 sources. Design a tiered assignment system where all students engage with the same essential question and the same 4 sources, but the scaffolding and product differ by tier. For Tier 1: specify the graphic organizer, sentence frames, and vocabulary glossary provided. For Tier 2: specify the annotation protocol and guided analysis questions. For Tier 3: specify the additional source, the comparative analysis frame, and the extended writing prompt. Include the teacher planning process for managing three tiers in one 50-minute class and how you return papers without stigmatizing tiers.","tags":["differentiation","tiered-assignments","history","high-school","primary-sources"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-26","title":"ADHD Executive Function Support System for a 6th-Grade Team","prompt":"You are a 6th-grade team leader at a middle school where three students transitioning from elementary have ADHD with significant executive function deficits — they struggle with organization, task initiation, and sustaining attention for more than 10 minutes. Design a cross-subject executive function support system that the 4-teacher team implements consistently. Include: a daily agenda structure with visual timers and transition warnings that works across all four classrooms, a homework tracking system using Google Classroom that reduces the cognitive load of remembering assignments, a desk organization protocol with a visual checklist laminated on each student's desk, a body-doubling and movement break schedule embedded into each 50-minute class period (specify when and how long), and a weekly 5-minute teacher-student check-in template that builds metacognitive skills and tracks which strategies the student reports are working. Include guidance on how to present these supports to the student without framing ADHD as a deficit.","tags":["differentiation","adhd","executive-function","middle-school","inclusion"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-27","title":"Scaffolded Close Reading for Striving 4th-Grade Readers","prompt":"You are a 4th-grade teacher with 7 students who are reading at a 2nd-grade level but are expected to access 4th-grade social studies content about state government. Design a scaffolded close reading sequence that allows these students to access a 4th-grade informational text about how a bill becomes a law without modifying the content standard. The sequence should span 3 days (each segment is 25 minutes within the literacy block): Day 1 focuses on building background knowledge using images, video, and a structured vocabulary preview of 8 key terms; Day 2 uses a chunked version of the text with partner reading and a graphic organizer; Day 3 focuses on a text-dependent writing task using sentence frames. Provide the complete graphic organizer template for Day 2, the 8 vocabulary terms with student-friendly definitions, and the sentence frame bank for Day 3. Include a note on how this work connects to the whole-class close reading happening simultaneously.","tags":["differentiation","striving-readers","literacy","elementary","scaffolding"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-28","title":"UDL Redesign for 11th-Grade Chemistry: Stoichiometry Unit","prompt":"You are an 11th-grade Chemistry teacher preparing a 3-week unit on stoichiometry for a class of 26 students that includes 4 students with IEPs (2 with processing disorders, 2 with anxiety disorders), 3 students who are long-term English Language Learners, and 5 students who are highly advanced and considering chemistry as a college major. Redesign the unit using Universal Design for Learning (UDL) principles across the three UDL guidelines: representation, action and expression, and engagement. For representation: specify 4 ways you present stoichiometry concepts beyond the textbook. For action and expression: describe 3 alternative ways students can demonstrate mastery of molar ratios. For engagement: identify 2 real-world contexts that connect stoichiometry to student interests and community relevance. Then create the student choice menu for the unit assessment, with 4 options at equivalent rigor, and the single rubric used to evaluate all four options.","tags":["differentiation","udl","chemistry","high-school","inclusion"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-29","title":"Kindergarten DIBELS-Based Reading Intervention Small Groups","prompt":"You are a kindergarten teacher running 20-minute small group reading interventions 4 days per week for your 8 lowest students while the other 14 students work in literacy centers. Your data from the DIBELS Next assessment shows 3 students need work on phonemic awareness (blending onset-rime), 3 students need letter-sound correspondence for consonants, and 2 students have no concepts about print. Design the small group rotation system: how you organize and signal three groups across 4 days, the exact activities and materials for each group's 20-minute block, two management strategies for keeping the 14 center students on task without interrupting your group, a weekly data collection tool you use during small groups (no longer than 2 minutes to complete), and what you do in Week 3 when one phonemic awareness student is ready to move to a more advanced group. Include the approximate cost of materials if purchased new.","tags":["differentiation","intervention","kindergarten","reading","small-groups"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-30","title":"Autism Spectrum Whole-Class Support Plan: 3rd-Grade Inclusion","prompt":"You are a 3rd-grade general education teacher with a student on the autism spectrum who has strong academic skills but significant challenges with unstructured time, unexpected changes to routines, and collaborative group work. The student's IEP goals include increasing peer interaction and managing transitions with fewer than 2 adult prompts. Design a whole-class-embedded support plan: a visual daily schedule posted and reviewed each morning with a specific protocol for announcing schedule changes at least 10 minutes in advance, a structured choice menu for free choice and indoor recess that eliminates the anxiety of open-ended time, a group work role structure that gives the student a predictable, clearly defined role (specify the role and its exact responsibilities), a sensory break menu with 4 self-selected regulation strategies the student can use without leaving the classroom, and a peer interaction skill of the month framework where you teach one social script to the whole class each month (provide the September and October social scripts). All supports should be framed as benefiting every student.","tags":["differentiation","autism","inclusion","elementary","social-skills"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 4. CLASSROOM MANAGEMENT (31-40) ---
  {"id":"edu-31","title":"First-Week Classroom Management Plan for a New High School Teacher","prompt":"You are a first-year 10th-grade English teacher at a large urban public high school with 6 class periods averaging 30 students each. You have been warned that this school has a challenging culture and that students will test boundaries in the first two weeks. Design your complete first-week classroom management plan: the physical arrangement of your room and your rationale, the 4-5 non-negotiable procedures you will explicitly teach and practice on Day 1 (specify how you teach each one — not just a list), your warm-up routine for the first 5 minutes of every class that gets students settled immediately, the positive and corrective language scripts you will use for the three most likely behavior challenges (phone use, side conversations, refusal to work), your acknowledgment system for the first month before you know students well, and the information you will send to parents in the first week. Ground every recommendation in specific, actionable language, not principles.","tags":["classroom-management","new-teacher","high-school","routines","first-week"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-32","title":"Restorative Conversation Protocol After a 7th-Grade Conflict","prompt":"You are a middle school 7th-grade teacher. During class today, two students had a heated verbal argument that disrupted the lesson for 10 minutes. You separated them and class continued, but the tension is unresolved and both students will be back tomorrow. You want to use a restorative approach rather than traditional punishment. Write the complete restorative conversation protocol: the individual conversation you have with each student separately after school today (include the exact 5 restorative questions you ask, how you listen, and what you are trying to learn), the joint restorative conference structure for tomorrow morning before school with both students and you (10-15 minutes, include the agreement they sign), the re-entry plan for how both students return to class and sit in a reconfigured arrangement, the 30-second check-in you do with each student at the door for the next 5 school days, and how you document this process for the student's file and communicate with their families within 24 hours.","tags":["classroom-management","restorative-practice","middle-school","conflict","behavior"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-33","title":"2-Week Re-Engagement Plan for a Checked-Out 9th-Grade Class","prompt":"You are a 9th-grade Biology teacher and it is February. Your 4th period class of 27 students has collectively checked out — compliance is low, energy is flat, and many students stare at their phones or put their heads down. You have tried proximity, calling on students cold, and positive narration, with minimal results. Design a 2-week re-engagement plan: Week 1 uses a class reset conversation (write the exact script, 5 minutes) where you name the dynamic without blaming, survey students about what would make class better (provide the 8-question survey), and relaunch class norms collaboratively. Week 2 introduces 3 structural changes to your lesson format to increase active engagement — specify each change, when in the lesson it occurs, what students are physically doing, and how you know it is working. Include how you handle the 4-5 students who are active resistors even after the reset, and what you communicate to the school counselor if the situation does not improve.","tags":["classroom-management","engagement","high-school","behavior","re-engagement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-34","title":"Classroom-Level PBIS System for 2nd Grade","prompt":"You are a 2nd-grade teacher at a school that uses PBIS (Positive Behavioral Interventions and Supports) at the school-wide level with the expectations Be Safe, Be Responsible, and Be Respectful. Your classroom of 24 students needs a classroom-level PBIS system that connects to the school system and is developmentally appropriate for 7-8 year olds. Design the complete classroom system: a visual display of your 3 classroom-specific behavioral expectations translated into observable behaviors (give 2 examples per expectation), your daily check-in/check-out routine that takes under 3 minutes, a whole-class incentive system that uses group points rather than individual competition (describe how it works, how points are earned, and what the celebration looks like when the class reaches the goal), your individual student support plan for the 3-4 students who need more than the whole-class system (Tier 2 — specify the intervention without naming students), and how you communicate with families about behavior weekly using a simple home-school communication tool.","tags":["classroom-management","pbis","elementary","behavior","systems"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-35","title":"Overhauling 5th-Grade Hallway Transition Behavior","prompt":"You are a 5th-grade teacher whose students are consistently the loudest and least orderly class in the hallway during transitions, which has generated complaints from other teachers and multiple conversations with your principal. Your students have 4 transitions per day: to specials, to lunch, to recess return, and to dismissal. Design a complete transition management overhaul for all 4 transitions: the explicit procedure for each transition including where students line up, the lining-up signal, the silence expectation, and the consequence for not meeting it, a practice schedule for the first 2 weeks where you reteach each transition until the whole class meets the standard 3 days in a row, a student leadership system where reliable students are assigned roles that give them ownership of the transition process, the language you use to acknowledge the class when a transition goes well (be specific — not just great job), and a communication plan to update your principal on progress weekly so they see you addressing it proactively.","tags":["classroom-management","transitions","elementary","procedures","behavior"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-36","title":"Classroom Phone Policy That Actually Gets Enforced: High School","prompt":"You are a 10th-grade social studies teacher at a school that has a phone policy on paper but zero enforcement culture — students use phones openly in class and other teachers have stopped addressing it. You have decided to create a phone management system in your classroom that is fair, consistent, and does not create power struggles. Design a classroom phone system: your exact policy statement (2-3 sentences, clear and unambiguous), the physical storage solution and how it is set up at the start of class each day, your calm, scripted first response when a phone appears (write the exact words), the escalation sequence if the student refuses (3 steps, including when the office gets involved), how you build student buy-in for the policy in the first week including a class discussion and a 5-minute activity connecting phone use to attention research, and how you handle the parent who emails to say their child must have the phone available for medical or family reasons. Include one built-in phone use moment per class period that reduces the feeling of deprivation.","tags":["classroom-management","phones","high-school","policy","behavior"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-37","title":"Accountable Group Work Structures for an 8th-Grade ELA Project","prompt":"You are an 8th-grade ELA teacher who has stopped using group work because it always devolves into one student doing everything while others socialize. You want to reintroduce structured collaborative learning for a research project on banned books. Design a group work system that ensures real interdependence and accountability for all 4 group members across 5 class periods: define the 4 roles with exact, non-overlapping responsibilities that make each student's contribution essential to the product, design an individual accountability check (not a group grade) that each student completes daily in 5 minutes, specify how you form groups (not student choice — explain your criteria), describe the 3-minute group launch protocol at the start of each work session that focuses the group's work time, include the teacher observation checklist you use while circulating to the 7 groups during a 25-minute work session, and write the project debrief conversation you have with a group where one member clearly did not contribute.","tags":["classroom-management","group-work","middle-school","ela","collaboration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-38","title":"Self-Regulating Morning Arrival Routine for 1st Grade","prompt":"You are a 1st-grade teacher with 21 students who arrive to school with varying levels of emotional readiness each morning — some come off buses dysregulated, some arrive hungry, some come from difficult home situations. Your school has 15 minutes of arrival time before the official school day begins. Design a morning arrival routine that: uses a self-check-in system (describe the physical setup and how a 6-7 year old interacts with it independently), includes 3 sensory regulation options students can choose from during arrival (specify each option, the materials, and where they are located in the room), sets up a predictable morning work activity that requires no teacher instruction so you can greet students individually at the door for a 5-second connection, includes a morning meeting of exactly 15 minutes with a greeting, a sharing round, and a class challenge, and connects the emotional check-in data to your day's instruction by identifying which students need extra support before the academic block begins. Write the Monday morning welcome message you post on the board.","tags":["classroom-management","morning-routine","early-childhood","sel","elementary"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-39","title":"In-Classroom De-escalation Protocol for a 6th-Grade Teacher","prompt":"You are a middle school 6th-grade teacher who has a student who occasionally becomes emotionally dysregulated in class — shouting, knocking over materials, and refusing to respond to adult direction. You have a class of 27 other students who need to continue learning. You are not a counselor, but the counselor takes 10-15 minutes to arrive. Design your in-classroom de-escalation protocol: the early warning signs you have learned to recognize (name 4 observable behaviors) and your immediate prevention response at that stage, your language and body language script for the first 60 seconds of a full escalation (write the exact words), the plan for the other 27 students during the escalation (who do they work with, what do they do, who do you signal for help), the safe physical space in your classroom where the student can regulate (describe the setup and what is available there), and the return-to-learning conversation you have with the student after the incident (5 specific questions). Include the documentation form you complete after each incident to track patterns.","tags":["classroom-management","crisis","de-escalation","middle-school","sel"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-40","title":"Substitute-Proof 3-Day Classroom Plan for 4th Grade","prompt":"You are a 4th-grade teacher who has been absent frequently this year due to a family health situation and your classroom falls apart when you are gone — students walk all over substitutes and come back with no work completed. You have a long-term sub covering for 3 days next week. Design a substitute-proof classroom management system: a printed Sub Binder with a 1-page classroom overview (routines, key students to know, and emergency contacts), fully scripted lesson plans for each of the 3 days in the binder that a person with no subject matter expertise can run (specify the subject, activity, instructions, materials location, and what to do if students finish early), a student helper system where 3 reliable students have designated roles during sub days (define each role), the exact language you teach your students before you leave about your expectations during sub days, and the accountability system (specify what students turn in and what you review when you return that allows you to identify who did and did not meet expectations). Include a note on one student who needs a specific support the sub must provide.","tags":["classroom-management","substitute","elementary","systems","planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 5. HIGHER EDUCATION (41-50) ---
  {"id":"edu-41","title":"Redesigning a Lecture-Heavy Intro Sociology Course with Active Learning","prompt":"You are a professor who teaches Introduction to Sociology to 120 first-year students at a regional public university where many students are first-generation college students and hold part-time jobs. Your current 75-minute Monday-Wednesday-Friday lecture format has low attendance (averaging 60%) and dismal exam performance. You want to redesign the course using active learning without requiring major technology investment. Design the redesigned course structure: a new class session template that limits lecture to no more than 25 minutes, incorporates two structured active learning activities into every session (describe 3 activity types you will rotate), a low-stakes participation system that incentivizes attendance without penalizing students who have work conflicts, a revised assessment structure that replaces two of the three midterm exams with alternative assessments better suited to first-generation students, and a first-day-of-class plan that establishes the active learning culture and explains why you teach this way. Include the syllabus language explaining the course redesign philosophy to students.","tags":["higher-ed","active-learning","sociology","course-design","first-generation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-42","title":"Facilitating a Graduate Seminar on Postcolonial Theory","prompt":"You are a professor facilitating a weekly 3-hour graduate seminar on postcolonial theory with 12 doctoral students in their 2nd and 3rd years. The reading load is 120-150 pages per week. Discussion quality varies wildly — 3 students dominate, 4 contribute when called on, and 5 rarely speak unless directly addressed. Design a semester-long discussion facilitation plan: a rotation system where each student leads one discussion per semester with a structured preparation protocol (what the discussion leader must prepare before class and how they open the session), your weekly discussion facilitation moves — specify 5 different discussion moves you use and when you deploy each one, a written reflection assignment students complete after leading their session and after being a participant, a mid-semester discussion audit where you share participation data with the class without identifying individuals and use it to set collective norms, and how you handle the session when the assigned reading generates no genuine disagreement among students.","tags":["higher-ed","graduate","seminar","discussion","facilitation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-43","title":"Inclusive Undergraduate Syllabus: Media, Technology and Society","prompt":"You are a professor designing the syllabus for a new upper-division undergraduate course called Media, Technology, and Society in a Communications department at a mid-sized public university. The course will have 35 students, typically juniors and seniors with varied backgrounds. You want the syllabus to function as both a legal document and a welcome document that reflects your pedagogical values and sets a tone of high expectations and genuine care. Write the full syllabus including: a course description paragraph that conveys intellectual excitement, 5 learning outcomes written in measurable behavioral terms, a weekly schedule for a 14-week semester with readings for each week (name real books and articles — no placeholders), a grading policy with weights, an attendance and late work policy that is humane but firm, a technology use policy, an accessibility and accommodation statement that goes beyond legal compliance, and a section called How to Succeed in This Course that gives students 6 concrete, actionable strategies.","tags":["higher-ed","syllabus","course-design","undergraduate","inclusion"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-44","title":"Active Learning in a 200-Student Introduction to Psychology Lecture","prompt":"You are a professor teaching Introduction to Psychology to 200 undergraduates in a tiered lecture hall with fixed seating. The course is required for multiple majors and the energy in the room often feels like students are watching television. You want to add 3 active learning structures that work at scale without clickers or expensive technology, in a room where students cannot easily turn their desks. Design the engagement overhaul: a think-pair-share protocol adapted for fixed seating (how do you manage noise, timing, and the pair dynamic), a problem-posing lecture technique where you pause 3 times per 50-minute lecture and describe exactly what students do during each pause, a polling strategy using mobile phones with Poll Everywhere or a show-of-hands protocol for conceptual questions (give 3 example questions for the memory unit), the written reflection students complete in the last 3 minutes of every class and how you process that data before the next session, and how you manage the students in the back rows who are visibly disengaged.","tags":["higher-ed","large-lecture","engagement","psychology","active-learning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-45","title":"Redesigning an Asynchronous Online Community College History Course","prompt":"You are an instructional designer collaborating with a History professor at a community college to redesign an asynchronous online US History I course for 35 students, many of whom are working adults with limited online learning experience. The previous version of the course had a 40% withdrawal rate, largely due to student isolation and confusion about expectations. Redesign the course structure for a 16-week semester: a weekly module template that creates predictable rhythm (specify the components, how many items are in each module, and the maximum time commitment per week), a community-building strategy for an asynchronous course (not just a discussion board — describe a more innovative approach), a formative feedback system that gives students substantive feedback within 72 hours without overwhelming the professor, a clear communication protocol (response time, office hours, preferred contact method) that reduces student anxiety, and a midterm course evaluation process that allows the professor to adjust the second half of the course based on student feedback. Include the welcome video script for Week 1.","tags":["higher-ed","online-learning","community-college","course-design","asynchronous"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-46","title":"Writing-Intensive Political Science Course Without Grading Overload","prompt":"You are a professor teaching a 28-student upper-division writing-intensive Political Science course on comparative democracy. Your department requires the course to include substantial writing, but you currently teach 3 sections of this course and cannot spend 40 hours per week grading. Design a writing curriculum that maintains rigor and produces strong student writers without requiring you to write extensive comments on every paper. Include: a low-stakes writing sequence with 5 short assignments (specify each assignment's purpose, word count, and your 5-minute grading method), a portfolio capstone structure where students submit 3 revised pieces at the end of the semester (describe how revision is scaffolded), a peer review system that generates feedback of actual quality (give the protocol, the training students receive in Week 2, and the accountability mechanism), your use of a single focused comment per draft instead of comprehensive line edits (write 3 example focused comments), and a transparent grading approach using a single-point rubric that takes under 8 minutes per paper to apply.","tags":["higher-ed","writing","grading-efficiency","political-science","assessment"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-47","title":"Semester Mentoring Plan for 4 Undergraduate Research Assistants","prompt":"You are a professor at a liberal arts college who has 4 undergraduate research assistants working in your cognitive psychology lab for the spring semester. Two are first-year students who have never done research, one is a junior who wants to pursue a PhD, and one is a senior writing an honors thesis. Design a semester-long mentoring structure that develops all four students appropriately: a weekly 60-minute lab meeting agenda that serves all four levels (specify each section of the meeting and what each student contributes), an individualized development plan for each of the four students with 2 specific skill goals and a check-in milestone at Week 8, a scaffolded research writing curriculum for the honors thesis student from literature review to final draft, guidance for supervising the first-year students' first experience with data collection including the training protocol and their first independent task, and how you have the PhD-track junior build conference presentation skills by the end of the semester.","tags":["higher-ed","undergraduate-research","mentoring","lab","advising"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-48","title":"Flipping a Graduate Education Research Methods Course","prompt":"You are a professor teaching a graduate-level Research Methods course to 18 second-year master's students in an Education program. Class meets once per week for 2.5 hours. Currently you spend the first 45 minutes lecturing on methodology concepts and students leave with more questions than clarity. You want to flip the content delivery so class time is used for application and problem-solving. Design the flipped course structure: a pre-class learning module template (specify the components — video length, reading length, formative check, and expected time commitment), the in-class session template for a 2.5-hour class using flipped content on Mixed Methods Research Design (specify what happens in each 30-minute block), the accountability mechanism that ensures students actually complete the pre-class work, how you handle the students who consistently arrive unprepared, and a comparison of two students' experiences in your course before and after the flip to illustrate what changes. Include the pre-class module for the session on survey design as a concrete example.","tags":["higher-ed","flipped-classroom","graduate","research-methods","course-design"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-49","title":"University Academic Integrity Policy for an AI-Enabled World","prompt":"You are the chair of an Academic Integrity committee at a mid-size public university being asked to draft updated academic integrity guidelines for a world where students have access to AI writing tools. Your current honor code was written in 2015 and is inadequate. Draft updated policy guidance including: a working definition of academic dishonesty that explicitly addresses AI-generated text (be specific about what is and is not permitted), a tiered AI use framework with 3 levels that faculty can adopt for their courses (prohibited, limited use with disclosure, fully permitted), the disclosure language students must include when they use AI tools in permitted contexts, a faculty guidance document on assignment design that reduces AI-enabled cheating (give 5 specific assignment types that resist AI generation), a student communication explaining the new policy and the reasoning behind it (aim for an undergraduate reading level), and a process for investigating suspected AI misuse that is fair to students including how you distinguish AI text from human text and the evidentiary standard required before sanctions.","tags":["higher-ed","academic-integrity","ai-policy","university","ethics"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-50","title":"First-Generation Student Support Integration in Calculus II","prompt":"You are a professor teaching Calculus II to 45 undergraduates at a university where 55% of students are first-generation college students, many of whom feel they do not belong in advanced STEM courses. Three students dropped the course in Week 2 after the first quiz. Design a comprehensive first-generation student support integration into your course: office hours redesign that moves from passive availability to proactive structured sessions (describe the format, the schedule, and how you communicate about them), a study group scaffolding system for the first 4 weeks that teaches students how to study together before releasing them to self-organize, an early alert system triggered by specific performance indicators (name 3 indicators) that connects struggling students to tutoring resources within 48 hours, a mindset and belonging intervention embedded into the first 3 weeks of class (describe 3 specific moments where you address imposter syndrome and math identity), and a mid-semester pulse survey (provide the 7 questions) that helps you identify which students need outreach before they stop attending.","tags":["higher-ed","first-generation","stem","calculus","belonging"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 6. INSTRUCTIONAL TECHNOLOGY (51-60) ---
  {"id":"edu-51","title":"Launching Google Classroom for a Paperless 8th-Grade Science Class","prompt":"You are an 8th-grade science teacher transitioning your classroom to fully paperless using Google Classroom for the first time. You have 112 students across 4 periods, all with school-issued Chromebooks. It is the week before school starts. Design the complete Google Classroom setup and onboarding plan: the folder and classwork organization structure for the first quarter (specify how you organize by week, topic, or unit and why), the first-day student onboarding routine that gets all 112 students into Google Classroom and submitting their first assignment in a single 50-minute period, your naming convention for all assignments and how you enforce it so your gradebook stays manageable, three Google Classroom features beyond basic assignment posting that you will use in the first month and how each one saves you time, a workflow for returning written feedback on Google Docs so students actually read and respond to comments, and a parent communication plan for families unfamiliar with Google Classroom including a 1-page printed guide you send home in Week 1.","tags":["instructional-tech","google-classroom","middle-school","science","paperless"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-52","title":"Weekly EdTech Formative Routine: 6th-Grade Social Studies","prompt":"You are a 6th-grade social studies teacher who wants to build a sustainable EdTech formative assessment routine using free tools. You have 30 students with school iPads, reliable WiFi, and a 50-minute class period. Design a weekly formative tech routine: Monday uses a Padlet collaborative brainstorm to activate prior knowledge (describe the setup and the prompt type), Wednesday uses Kahoot for a 10-question vocabulary review (write 5 actual sample questions about ancient civilizations with 4 answer choices each), Friday uses a Google Form exit ticket that auto-generates a summary report you can review in 5 minutes. Also specify: how you handle the 4 students whose iPads have connectivity issues during tech activities, how you train students to use each platform in the first 2 weeks so that the transition to tech never takes more than 90 seconds, the data from Wednesday's Kahoot that you use to adjust Thursday's instruction, and one alternative for each tool in case the school's filter blocks it.","tags":["instructional-tech","formative-assessment","kahoot","middle-school","social-studies"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-53","title":"Blended Learning Station Rotation with Lexia Core5: 4th-Grade Reading","prompt":"You are a 4th-grade reading teacher implementing a blended learning rotation model using Lexia Core5 as the adaptive technology component. Your class of 26 students has 6 different reading levels, and you need to provide targeted small group instruction daily during a 90-minute reading block. Design the complete blended rotation model: the three rotation groups and how you assigned students to them using reading level and engagement data, the exact schedule for the 90-minute block showing what each group is doing during each 30-minute rotation, the Lexia Core5 implementation protocol (how long students work, what the teacher monitors, and how you use the data reports generated), your small group lesson structure for the 30-minute teacher-led group (what happens in each 10-minute segment), the independent reading and written response activity students do during the third rotation, and a parent communication explaining the rotation model that addresses the most common parent concern about kids using computers all day.","tags":["instructional-tech","blended-learning","lexia","elementary","reading"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-54","title":"Teaching Critical AI Literacy in an 11th-Grade Research Unit","prompt":"You are an 11th-grade English teacher who wants to teach students to use AI writing tools ethically and critically rather than banning them. Your school has no official AI policy yet. You are beginning a 6-week research paper unit and you want AI to be part of the process in limited, scaffolded ways. Design the AI integration plan for this unit: a classroom AI use policy you draft with students in Week 1 (describe the co-creation process and the 4 non-negotiable rules you bring to the discussion), three specific AI-assisted tasks that genuinely improve student learning (specify the task, the AI prompt students use, and what they do with the AI output), two tasks that are AI-prohibited and why you explain that prohibition to students, a lesson on evaluating AI-generated text for accuracy and bias using a specific research topic as the test case, and the disclosure statement students include in their final paper explaining how they used AI. Include one example of an AI prompt a student would write and the follow-up critical evaluation questions they answer about the response.","tags":["instructional-tech","ai-tools","english","high-school","research"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-55","title":"Student Documentary Film Project: 8th-Grade Media Literacy","prompt":"You are a middle school 8th-grade Media Literacy teacher whose students will produce 2-3 minute documentary shorts on local community issues as their final project. Your class has 28 students, access to school iPads with iMovie, and 6 weeks before the project deadline. Design the complete video production unit: a scope and sequence showing what students learn each week (pre-production in Weeks 1-2, production in Weeks 3-4, post-production in Week 5, screening in Week 6), the storyboard template students complete before filming begins, a 4-criterion project rubric for the documentary covering argument and evidence, visual storytelling, audio quality, and editing, the peer critique protocol students use after rough cut screenings in Week 5, a community screening event plan for Week 6 (where, who is invited, how projects are displayed), and the safety and consent protocol students follow when filming people outside the school. Include the media release form template.","tags":["instructional-tech","video-production","media-literacy","middle-school","project"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-56","title":"Desmos Conceptual Exploration Before Algebra II Polynomials","prompt":"You are an Algebra II teacher at a comprehensive high school with 24 students who are on track for college but struggle with the why behind mathematical procedures. You want to use Desmos to build conceptual understanding of polynomial functions before introducing the algebraic procedures. Design a 3-day Desmos exploration sequence before the formal polynomial unit: Day 1 students use Desmos to explore how the degree of a polynomial affects its graph shape (design 5 specific Desmos activity prompts that guide this discovery), Day 2 students investigate end behavior by manipulating leading coefficients (write 4 investigation questions with expected student responses), Day 3 connects graphical observations to factored form by having students match graphs to equations. For each day specify the Desmos activity structure (teacher-paced vs. student-paced), the class discussion moves that connect Desmos exploration to mathematical vocabulary, and the 3-question pencil-and-paper exit ticket that checks whether the conceptual understanding transfers off the screen.","tags":["instructional-tech","desmos","algebra","high-school","math"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-57","title":"Civil Rights Movement Podcast Project: 10th-Grade US History","prompt":"You are a 10th-grade US History teacher who wants students to create 8-10 minute podcast episodes on turning points in the Civil Rights Movement as an alternative to the traditional research paper. Your class of 29 students has school Chromebooks, access to Audacity or GarageBand, and you have 4 weeks. Design the complete podcast project: the list of 10 Civil Rights Movement topics students can choose from (ensure geographic and demographic diversity in the topics), the research and script development process in Weeks 1-2 including the annotated bibliography requirement, the recording and editing protocol in Week 3 including the studio setup using a closet or hallway and the technical training session, the peer feedback protocol for rough recordings before final submission, a 5-criterion rubric covering historical accuracy, argument, audio quality, pacing, and source integration, and the public sharing plan (podcast platform, class website, or school radio) that gives students an authentic audience. Include guidance for students who are anxious about their recorded voice.","tags":["instructional-tech","podcast","history","high-school","project"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-58","title":"1:1 Chromebook Classroom Management Plan for 3rd Grade","prompt":"You are a 3rd-grade teacher who just received a class set of 24 Chromebooks through a district grant. You have never managed a 1:1 device classroom before. It is August. Design the complete device management system for the first month: the physical setup of the device storage cart and the checkout and return procedure students can execute independently, the 4 non-negotiable device use rules you teach in the first week (specify the lesson for each rule — not just the rule), your signal for screens closed and eyes on me and the practice routine for the first 2 weeks, the digital citizenship mini-curriculum for the first 4 Fridays covering passwords, online behavior, evaluating websites, and cyberbullying, a troubleshooting protocol students follow before asking the teacher for tech help (the 3 steps they take independently first), and the parent communication about home device use for students whose family might not have WiFi (specify the offline access solution you provide).","tags":["instructional-tech","device-management","elementary","chromebook","digital-citizenship"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-59","title":"Google Cardboard VR Solar System Lesson for 5th Grade","prompt":"You are a 5th-grade science teacher at an under-resourced school where students rarely leave their urban neighborhood. You have access to 6 Google Cardboard headsets and class iPads through a district grant. You are teaching the solar system (NGSS 5-ESS1). Design a virtual reality learning experience around a 45-minute solar system tour: the 3 VR applications or YouTube 360-degree experiences you will use (name them specifically and explain what each one shows), a pre-VR preparation activity that gives students the scientific vocabulary to observe meaningfully, the structured observation guide students complete during the VR experience (specify 6 things they must document), the group rotation system for sharing 6 headsets among 24 students so all students have 2 headset turns during the 45 minutes, a post-VR discussion protocol that connects the experience to the NGSS standard, and the culminating task where students use their VR observations to write a scientific explanation comparing two objects in the solar system. Include contingencies if the headsets malfunction.","tags":["instructional-tech","vr","science","elementary","solar-system"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-60","title":"Data Dashboard Protocol for a 6th-Grade Teacher Team","prompt":"You are a middle school instructional technology coach helping a 6th-grade team of 4 content teachers use their school's data dashboard (Illuminate Education or a similar platform) to drive weekly instructional decisions. The team has data from weekly common assessments but has never used it systematically — they meet for 45 minutes on Thursdays but spend most of the time sharing anecdotes. Design the data-driven team meeting protocol: a 10-minute pre-meeting protocol where each teacher pulls 3 specific data points from the dashboard before Thursday (specify the 3 data points), the 45-minute Thursday meeting structure with timed segments for data analysis (15 min), root cause discussion (10 min), instructional response planning (15 min), and logistics (5 min), a data display template each teacher brings to the meeting, the 2 instructional response options the team considers when more than 40% of students miss a standard, and the follow-up accountability check-in at the following Thursday's meeting. Include guidance for the teacher who does not yet trust the data.","tags":["instructional-tech","data","team-collaboration","middle-school","assessment"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 7. STUDENT WRITING SUPPORT (61-70) ---
  {"id":"edu-61","title":"5-Minute Writing Conference System for a 6th-Grade Narrative Unit","prompt":"You are a 6th-grade ELA teacher preparing to hold 5-minute individual writing conferences with each of your 28 students during a narrative writing unit. You have 45 minutes of independent writing time per day over a 2-week period, which means you can see each student approximately twice. Design the complete writing conference system: the conference scheduling and sign-up structure that you manage without losing instruction time, the 5-minute conference structure (opening question, listening phase, one teaching point, student goal-setting, closing) with specific language for each phase, a conference note-taking form you complete in under 90 seconds that is also useful when conferring with the same student the following week, the 5 most common 6th-grade narrative writing issues you will likely address and your one teaching move for each, how you handle the student who insists their writing is fine and does not want feedback, and the student conference self-preparation tool (a short form students complete before sitting down with you so the conference stays focused on what they need).\n\n[Paste the student's essay or work sample]","tags":["writing","conference","middle-school","ela","feedback"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-62","title":"3-Day Thesis Workshop for 10th-Grade Literary Analysis","prompt":"You are a 10th-grade English teacher and after reading your first set of literary analysis essays on The Great Gatsby, you have discovered that 22 of your 27 students wrote thesis statements that are either topic sentences, factual statements that require no argument, or three-pronged road maps with no interpretive claim. Design a 3-day thesis workshop (each day is 25 minutes embedded in the class period): Day 1 diagnoses the problem using 6 anonymous thesis examples from your class (write the 6 examples at different levels and the discussion protocol for analyzing them), Day 2 teaches the arguable claim using the So what, Who cares revision protocol with 4 practice theses students revise, Day 3 students write and workshop their revised Gatsby thesis with a partner using a specific feedback protocol. Include the one-sentence definition of a strong thesis you post permanently, the 4 diagnostic questions students ask of any thesis statement they write, and the revision you expect from students when they resubmit their essay opening.","tags":["writing","thesis","high-school","english","literary-analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-63","title":"60-Minute Revision Workshop for 8th-Grade Persuasive Essays","prompt":"You are an 8th-grade ELA teacher whose students treat revision as spell-checking. When you return drafts, students change a few words, fix punctuation, and resubmit with no substantive improvement. You want to teach real revision as a skill during a persuasive essay unit. Design a 60-minute revision workshop: a 10-minute opening that distinguishes revision (meaning, argument, structure) from editing (mechanics) using two real 8th-grade writing samples (write abbreviated versions of each), a 15-minute focused revision lesson on paragraph-level coherence using the PEEL structure where students evaluate whether each paragraph has a clear point, evidence, explanation, and link, a 25-minute independent revision session where students use a 3-color highlighting protocol (highlight claims in yellow, evidence in green, explanation in blue) to diagnose gaps in their own essay, a 10-minute partner share where students identify one specific revision they will make and write the new version on a revision slip. Provide the revision slip template and describe what you collect at the end of class to hold students accountable for the revision.","tags":["writing","revision","middle-school","persuasive","workshop"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-64","title":"Scaffolded Writing Support for WIDA Level 3-4 ELL Students in 7th Grade","prompt":"You are a 7th-grade ELA teacher with 9 English Language Learners at intermediate proficiency level (WIDA Level 3-4) in a class of 26 students. Your class is writing a 4-paragraph informational essay on a science topic connected to your cross-curricular unit. These students have the ideas and the content knowledge but struggle with academic English sentence construction and paragraph organization. Design a scaffolded writing support plan that runs parallel to whole-class instruction: a sentence frame bank organized by paragraph function (provide 4 frames for topic sentences, 4 for evidence introduction, 4 for explanation, 4 for conclusion) that ELL students use as a resource not a crutch, a paragraph frame (visual organizer with sentence-level boxes) for the body paragraph, a vocabulary resource they build themselves over the unit using a Frayer model for 10 key academic words, a peer writing partnership protocol where each ELL student is paired with a patient, strong writer for 15 minutes during drafting, and the modification to your writing rubric that assesses content and organization separately from language conventions for ELL students at this proficiency level.","tags":["writing","ell","middle-school","scaffolding","informational"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-65","title":"4-Day Patchwriting Intervention for AP Language Students","prompt":"You are an 11th-grade AP Language teacher preparing students for the AP synthesis essay and a semester research paper. Your students chronically patchwrite — lifting phrases directly from sources with minimal paraphrase — and you suspect many do not understand what synthesis actually means. Design a 4-day patchwriting intervention early in the semester: Day 1 students analyze a deliberately patchwritten passage (write a 150-word example) alongside the source text, identify what makes it patchwriting, and name 3 characteristics, Day 2 students practice the 3-step summary technique (read, cover, write from memory, compare), Day 3 introduces the conversation metaphor for synthesis — sources as voices in a debate — and students practice entering the conversation with one original observation, Day 4 students revise a patchwritten paragraph from their own draft into genuine synthesis. Include the teacher model of the Day 3 conversation technique using two real articles about a current debate topic, and the self-assessment checklist students use on Day 4 before submitting the revision.","tags":["writing","research","ap-language","high-school","synthesis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-66","title":"Daily 10-Minute Writing Fluency Routine for 4th Grade","prompt":"You are a 4th-grade teacher who wants to build a daily 10-minute writing fluency routine that develops students as writers over the school year without requiring daily teacher grading. Your class of 25 students has very uneven writing skills — 8 students write prolifically and eagerly, 10 write adequately but slowly, and 7 find writing physically and cognitively painful and produce minimal output. Design the full-year daily writing routine: the 3 different prompt types you rotate through the week (Monday and Wednesday are one type, Tuesday and Thursday another, Friday a third — name and describe each type), the physical setup of the writing notebook and the only rule about what goes in it, your non-grading teacher response system where you read and respond to 5 different notebooks each day on a rotation so every student gets a teacher response every week (describe your response format — no more than 2 sentences per student), how you differentiate the routine for the 7 struggling writers without singling them out, and the twice-per-semester celebration activity where the class shares from their notebooks voluntarily.","tags":["writing","fluency","elementary","daily-practice","4th-grade"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-67","title":"Oral-to-Written Argument Bridge Unit for 9th-Grade English","prompt":"You are a 9th-grade English teacher who has found that students argue well verbally but fall apart when they try to put an argument in writing — they lose the logical thread, omit evidence, and write conclusions that simply restate the introduction. Design a 2-week unit that bridges from oral argument to written argument on the topic of whether social media platforms should be regulated by the government. Week 1 uses structured academic controversy (days 1-2), Socratic seminar (day 3), and argument mapping (days 4-5) where students visually map a spoken argument before writing it. Week 2 uses drafting (days 6-7), revision focused on counterargument (days 8-9), and final submission and reflection (day 10). For each day specify the activity, the student product, and the connection to the writing standard. Provide the argument map template from Day 5, the counterargument workshop protocol from Day 8, and the 4-criterion rubric used to assess the final essay.","tags":["writing","argument","debate","9th-grade","english"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-68","title":"Supporting Reluctant and Avoidant Writers During 8th-Grade Memoir","prompt":"You are a middle school 8th-grade teacher with 5 students who actively avoid writing tasks — they stare at blank pages, make excuses, leave assignments incomplete, and appear to shut down entirely when writing is required. Two of these students have IEPs, one has undiagnosed anxiety, and two simply have a long history of failure with writing tasks. Design an individualized support approach for reluctant writers during a memoir writing unit: the 3 low-threat entry points you use before any formal writing begins (describe each activity and why it builds safety), a verbal-to-written bridge strategy where students dictate ideas before writing (specify the tool and protocol), the modified product options for students who cannot produce a full draft by the deadline (3 alternatives, each requiring genuine effort but different written output), the private encouragement protocol you use at the start and end of each class period with these 5 students, and the conversation you have with each student individually in Week 1 about their writing history (5 specific questions you ask to understand their experience, not to diagnose it). Include the language you avoid because it increases avoidance.","tags":["writing","reluctant-writers","middle-school","memoir","support"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-69","title":"In-Class College Essay Coaching for First-Generation 12th Graders","prompt":"You are a 12th-grade English teacher at an under-resourced public school where most students are first-generation college applicants and have never received private college counseling. It is October and your seniors are writing Common App personal statements. Most students have chosen safe, generic topics and are writing them in a flat, reportorial style that will not distinguish them in an admissions pool. Design a 3-week, in-class college essay coaching curriculum embedded in English class for 25 seniors: a 45-minute find your story workshop using specific brainstorming protocols (not just write about something important to you), a 30-minute lesson on the difference between a topic and a theme using 2 contrasting essay excerpts, a peer feedback protocol designed for personal writing where feedback feels supportive not critical, individual 10-minute coaching conferences using 3 specific questions you ask every student regardless of where they are in their draft, and the essay submission checklist students use before their teacher submits on their behalf. Include guidance for the student whose essay draft is about trauma and requires a sensitive approach.","tags":["writing","college-essay","12th-grade","first-generation","coaching"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-70","title":"Grammar-in-Context: Eliminating Run-Ons in 6th-Grade Writing","prompt":"You are a 6th-grade ELA teacher who has data showing that 18 of your 28 students make consistent comma splice and run-on sentence errors in their writing. You have tried teaching grammar in isolation through worksheets and the errors have not decreased. Design a 4-week grammar-in-context approach where grammar instruction is embedded in the writing students are already doing. Week 1 uses diagnosis through the students' own writing samples (describe the analysis protocol — anonymous, projected, class discussion), Week 2 uses targeted mini-lessons of exactly 8 minutes at the start of class on the 3 most common errors (write the mini-lesson structure — mentor text, notice, practice, apply), Week 3 has students revise 2 paragraphs of their current essay using a checklist targeted at the taught errors, Week 4 has students become grammar editors for a partner's essay. Provide the 8-minute mini-lesson plan for comma splices, the self-editing checklist for Week 3, and the grammar mastery self-assessment students complete at the end of the 4 weeks.","tags":["writing","grammar","middle-school","ela","instruction"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 8. STEM EDUCATION (71-80) ---
  {"id":"edu-71","title":"5E Model Lesson: Newton's Second Law in 8th-Grade Science","prompt":"You are an 8th-grade Physical Science teacher at a Title I middle school where students have limited exposure to scientific thinking and most have never been asked to design their own investigation. You are teaching Newton's Second Law (F=ma) using the 5E instructional model. Design the complete 5E lesson spanning 3 class periods of 50 minutes each: Engage (Day 1, 10 min) — describe a discrepant event using a collision demonstration that creates cognitive dissonance, Explore (Day 1, 40 min) — students investigate the relationship between force, mass, and acceleration using fan carts and motion sensors (describe the setup, the data table, and the guided inquiry questions), Explain (Day 2, 30 min) — students construct the F=ma relationship from their data and you connect it to Newton's formal law, Elaborate (Day 2, 20 min, and Day 3, 30 min) — students apply the law to design a solution to a real engineering challenge (specify the challenge), Evaluate (Day 3, 20 min) — a performance task where students predict and explain the motion of a new scenario using F=ma. Include the data collection sheet and the performance task prompt.","tags":["stem","physics","5e-model","middle-school","inquiry"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-72","title":"6-Week Unplugged Computer Science Unit for 4th Grade","prompt":"You are a 4th-grade teacher integrating computer science into your classroom for 30 minutes on Fridays, starting with no prior CS experience for yourself or your students. Your school has no computer lab, but students will eventually code on Chromebooks. Design a 6-week unplugged CS unit that builds computational thinking before any screen coding: specify the activity for each of the 6 Fridays (draw from established unplugged CS curricula like CS Unplugged or Code.org's unplugged activities — name each activity, its duration, and the CT concept it teaches), include a student vocabulary list of 8 computational thinking terms introduced over the 6 weeks with student-friendly definitions, design a culminating activity in Week 6 where students write an algorithm for a physical task (specify the task and how you assess the algorithm), write the parent letter introducing the CS integration, and outline the 4-week online coding transition plan using Code.org's CS Fundamentals course that follows the unplugged unit. Include your self-study plan as a teacher who is new to CS.","tags":["stem","computer-science","unplugged","elementary","computational-thinking"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-73","title":"Number Talks and Multiplication Discourse for 3rd Grade","prompt":"You are a 3rd-grade math teacher committed to developing number sense through mathematical discourse rather than memorization drills. Your class of 24 students is beginning multiplication. You want students to develop multiple strategies before being introduced to the standard algorithm. Design a 3-week math talk intensive for multiplication: a daily 10-minute number talk protocol (write 5 specific number talk problems and the discussion moves you use for each one), a week-by-week strategy progression from equal groups to arrays to skip counting to the area model (specify what is introduced each week and how strategies build on each other), the mathematical discussion norms you establish in Week 1 with student-friendly language, the three student discourse moves you teach students to use with each other, and the formative observation tool you use during number talks to track which strategies each student uses and whether they can explain their reasoning. Provide 3 specific number talk problems for Week 2 with anticipated student strategies and teacher response moves.","tags":["stem","math","number-sense","elementary","discourse"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-74","title":"2-Week Bridge Engineering Design Challenge for 6th Grade","prompt":"You are a 6th-grade science teacher designing a 2-week engineering design challenge unit on structures and forces, aligned to NGSS MS-ETS1. Students will design and build a bridge using only index cards, tape, and paperclips that can hold the maximum weight over a 30cm span. Your class of 30 students has never done formal engineering design. Design the complete unit: a daily scope and sequence for 10 class periods of 45 minutes each, the guided research phase (Days 1-2) where students investigate 3 real bridge designs and identify structural principles, the design phase protocol (Day 3) including the technical drawing template and design review checklist, the build and test phase (Days 4-6) with the testing protocol and data recording sheet, the iteration requirement (each team must make at least one documented design change and explain why), the final load test event on Day 9 with class-wide data comparison, and the Day 10 design debrief using NGSS science and engineering practice language. Include the materials list and cost per team and the team role descriptions.","tags":["stem","engineering","ngss","middle-school","design-challenge"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-75","title":"AP Calculus AB Conceptual Launch: Intuitive Understanding of Limits","prompt":"You are an AP Calculus AB teacher at a high school where students are strong at algebraic procedures but struggle with conceptual understanding. It is the first week of school and you want to build an intuitive understanding of limits before introducing formal notation. Design a 4-day conceptual launch sequence: Day 1 uses a real-world context (describe a specific scenario involving instantaneous speed using a falling object or a car) to motivate the idea of a limit without using the word, Day 2 students use Desmos to explore the behavior of a rational function with a removable discontinuity by zooming in near the problem point (write 6 specific questions that guide the exploration), Day 3 introduces formal limit notation after students have built the intuition and you connect their Desmos observations to the definition (include the specific connection language you use), Day 4 is a gallery walk where each pair of students gets a different function with a problematic point and presents their limit analysis to the class. Provide the Day 2 investigation worksheet and the Day 4 gallery walk template.","tags":["stem","calculus","desmos","high-school","conceptual-teaching"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-76","title":"First 4 Weeks of a High School Python Programming Elective","prompt":"You are a high school Computer Science teacher teaching Python for the first time to 22 students in a semester-long elective. Students range from absolute beginners to students who have done some Scratch or web HTML. You are using Replit as your development environment so students can work from any device. Design the first 4 weeks of the course: a scope and sequence table showing each day's topic, key concept, and coding task for the first 20 class periods (50 minutes each), the first day lesson that includes setting up Replit accounts, running the first print statement, and the expectation-setting conversation about debugging culture (write the debugging mantra you teach), the classroom coding culture norms specifically addressing how students help each other without just sharing answers, two pair programming activities in Weeks 2-3 with specific driver/navigator protocols, and the Week 4 mini-project (specify the project requirements, the rubric, and how students present). Include a note on how you handle students who are significantly more advanced than their peers.","tags":["stem","python","computer-science","high-school","coding"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-77","title":"Lab Reports That Require Real Scientific Analysis: 9th Grade","prompt":"You are a 9th-grade Integrated Science teacher who is frustrated that students write lab reports by filling in blanks rather than doing scientific thinking. Your students just completed a controlled experiment on how surface area affects reaction rate using Alka-Seltzer tablets. Design a lab report process that requires genuine analysis: a pre-lab writing prompt that elicits students' actual hypothesis with reasoning (not just I think this will happen), a during-lab data recording structure that requires real-time analysis questions rather than only data tables (provide the template with 3 embedded analysis prompts), the analysis section protocol requiring students to graph their data using Google Sheets, describe the trend, explain the trend using particle theory, and connect to real-world applications (provide 4 guiding questions), the conclusion framework using the CER (Claim-Evidence-Reasoning) structure with a model CER based on the Alka-Seltzer experiment, and a peer review checklist for the analysis and conclusion sections that a 9th grader can meaningfully use. Include the 3 most common analysis errors you see and how you address them.","tags":["stem","science-writing","lab-reports","high-school","cer"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-78","title":"Statistics Semester Capstone Project Support for High School Seniors","prompt":"You are a high school Statistics teacher whose 24 seniors are completing a semester capstone project where they collect real data, conduct statistical analysis, and present findings to a panel. It is Week 3 of a 10-week project. Students have chosen topics but most have poorly framed research questions that will not yield meaningful statistical analysis. Design the project support structure for the remaining 8 weeks: a research question workshop this week that diagnoses weak questions (provide 4 example weak questions and the revision protocol), a data collection plan review checklist for Week 4 (list the 8 criteria a valid data collection plan must meet), the statistical analysis requirements students must address in their analysis section including appropriate test selection (specify minimum requirements), a mid-project check-in conference protocol for individual 5-minute meetings with each of the 24 students in Week 6, the presentation format and panel structure for Week 10 (specify the panel composition, each student's time allotment, and the 3 panel questions every presenter must answer), and the grading rubric with 5 criteria.","tags":["stem","statistics","high-school","capstone","data-analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-79","title":"STEM Identity and Belonging Practices for AP Chemistry","prompt":"You are a high school Chemistry teacher who has noticed that your AP Chemistry course of 22 students has 18 students who are white or Asian, 3 Black students, and 1 Latina student. Data from your school shows that Black and Latina students are disproportionately discouraged from AP STEM courses during scheduling. You want to actively counter this in your classroom. Design a STEM belonging integration plan for your course: 3 specific curriculum content changes that put scientists of color at the center of the content rather than as a sidebar (name the scientists and the content connections), a classroom culture practice you implement from Day 1 that normalizes struggle and disrupts the smart student hierarchy, a discussion you facilitate in Week 2 on who gets told they are good at science and why (provide the discussion structure and your facilitation moves), mentorship and visibility structures that connect your 4 students of color to STEM professionals who share their background, and how you monitor and respond to the microaggressions that may occur in classroom discussion or group work.","tags":["stem","equity","belonging","chemistry","high-school"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-80","title":"Maker Space Introduction Week for 5th-Grade Design Thinking","prompt":"You are a 5th-grade teacher whose school has just opened a maker space with basic supplies: cardboard, hot glue guns (teacher use only), tape, scissors, string, rubber bands, recycled materials, basic circuits with LEDs and batteries, and 4 computers with Tinkercad. You have one full project week (5 days, 3 hours per day) to introduce students to maker culture. Design the complete maker space project week for 25 students: Day 1 introduces the design thinking process through a 30-minute warm-up challenge (specify the challenge, materials, and debrief questions), Days 2-3 students work in teams of 4-5 on a sustained design challenge (specify the challenge — it should require iteration and have a testable success criterion), Day 4 is the iteration and improvement day including a structured feedback gallery walk, Day 5 is presentations and reflection. Include the team roles, the documentation journal students keep each day, the failure celebration ritual you establish, and the safety protocols for the maker space. Write the 5 journal prompts for Days 1-5.","tags":["stem","maker-space","elementary","design-thinking","project-based"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 9. SOCIAL-EMOTIONAL LEARNING (81-90) ---
  {"id":"edu-81","title":"Trauma-Informed Classroom Framework for 9th-Grade English","prompt":"You are a 9th-grade English teacher at an urban public high school where your school counselor has told you that 60% of your students have experienced at least one adverse childhood experience (ACE). You are not a therapist, but you want your classroom to be a place where students feel safe enough to learn. Design a trauma-informed classroom framework: the 5 physical environment choices you make in your classroom that reduce anxiety and increase felt safety (be specific about furniture, lighting, display choices, and seating options), your predictable daily structure and how you communicate it so students always know what to expect, 3 specific instructional practices you modify based on trauma-informed principles (explain the standard practice, what you change, and why), the language you use and avoid during writing and discussion assignments that touch on difficult personal content, your self-care and boundary protocol for when a student discloses trauma to you (the 3 steps you take and what you say to the student), and how you share relevant information with your school counselor without violating student trust.","tags":["sel","trauma-informed","high-school","classroom-culture","equity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-82","title":"Full-Year Morning Meeting SEL Curriculum for 2nd Grade","prompt":"You are a 2nd-grade teacher who runs a 20-minute Morning Meeting every day using the Responsive Classroom framework. You want to plan the SEL focus for each month of the school year so that Morning Meeting intentionally builds social-emotional competencies across the year. Design the full-year Morning Meeting SEL curriculum: for each of the 9 school months specify the SEL focus competency (use CASEL framework language), 2 specific sharing prompt types that develop that competency, 1 group activity per month that builds that skill, and 1 morning message structure that reinforces the focus. Then write the complete Morning Meeting plan for one specific day in October (the belonging month) including the greeting, the sharing prompt and protocol, the activity with full instructions, and the morning message text. Include guidance for managing the student who dominates sharing time every day and the student who never volunteers to share.","tags":["sel","morning-meeting","elementary","responsive-classroom","2nd-grade"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-83","title":"Systematic New Student Integration Plan for a High-Mobility Middle School","prompt":"You are a 7th-grade team leader at a middle school that receives 3-5 new students per month due to the high mobility rate in your district. New students typically feel isolated for weeks before forming friendships, and academic performance suffers during the transition period. Design a systematic new student integration plan that the 4-teacher team implements consistently: a Day 1 protocol starting at the main office and ending at the end of the school day (specify every handoff and who is responsible), a peer ambassador system with 2 trained student ambassadors per incoming student (describe the ambassador training and their specific responsibilities in the first week), a teacher check-in schedule for the first 2 weeks (which teacher checks in on which day, for how long, and what they ask), an integration activity embedded in one class period in the first week that helps the new student connect with classmates around shared interests, and a 2-week status check conversation between the team and the student to identify if additional support is needed. Include the family welcome communication sent on Day 1.","tags":["sel","belonging","middle-school","transitions","community"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-84","title":"8-Session Mental Health Literacy Unit for High School Advisory","prompt":"You are a high school advisory teacher who runs a 30-minute period twice per week with 18 students. Your school's counselor has asked advisory teachers to deliver a 4-week mental health literacy unit aimed at reducing stigma, building help-seeking skills, and teaching basic coping strategies. You are a content teacher (History), not a counselor. Design the 8-session unit plan with appropriate boundaries: a session-by-session overview with goals, main activity, and 5-minute closing check for each of the 8 sessions (topics: stress vs. anxiety, depression awareness, coping strategies, help-seeking and barriers, supporting a friend in crisis, school and community resources, stigma and language, and personal wellness planning), the class agreements you establish in Session 1 that make disclosure safe without making the group a therapy group, 3 specific boundaries you maintain as a non-counselor teacher (what you do and do not do when a student shares something concerning), the referral protocol when a student's disclosure suggests they need professional support, and the parent communication sent home before the unit begins.","tags":["sel","mental-health","high-school","advisory","wellness"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-85","title":"Restorative Circle Curriculum for 6th-Grade Homeroom","prompt":"You are a 6th-grade homeroom teacher at a middle school where students are transitioning from a close-knit elementary school and many feel adrift and disconnected in the larger building. You want to use restorative circles to build genuine community in your homeroom of 26 students. Design a restorative circle curriculum for the first 8 weeks of school: a Week 1 introductory circle focused only on norms and the talking piece ritual (write the full circle plan: opening, 3 rounds, and closing — approximately 30 minutes), a progression of circle topics for Weeks 2-8 (name the topic and the type of circle — community building, check-in, or academic) that gradually deepens trust, the circle protocol document you give students so they understand their role, your facilitation moves for the 3 most challenging circle moments (silence after a question, a student who says something offensive, and a student who cries), and how you adapt the circle for the student whose IEP requires modified social participation expectations. Include the closing ritual you use every week.","tags":["sel","restorative-circles","middle-school","community","homeroom"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-86","title":"Whole-Class Emotional Regulation Toolkit for 1st Grade","prompt":"You are a 1st-grade teacher at a school in a high-poverty neighborhood where students frequently arrive dysregulated and the traditional expectation of sit down and be ready to learn is not working. You want to build a whole-class emotional regulation toolkit. Design the complete toolkit: the 5-zone or similar emotional check-in system you use (specify the system, the visual display, and the daily check-in routine that takes under 3 minutes), a calm-down corner in your classroom (describe the location, the contents including 5 specific items and how each helps regulate, and the student-use protocol), 4 whole-class co-regulation strategies you use during academic transitions when energy is too high or too low (name each strategy, describe it in detail, and say when you deploy it), a feelings vocabulary curriculum embedded in read-alouds throughout the year (name 6 specific picture books you use and the SEL focus of each), and the family education component where you teach parents the same toolkit vocabulary so it transfers home. Include the simple one-page home handout.","tags":["sel","emotional-regulation","early-childhood","elementary","k-2"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-87","title":"Classroom Repair Plan After Racial Microaggressions in 10th Grade","prompt":"You are a high school 10th-grade teacher with a racially diverse class of 28 students. In the past month, 3 microaggressions have occurred during class discussions — one where a white student made a comment that minimized the experiences of students of color, one involving an assumption about a student's academic ability, and one involving a physical boundary violation. You did not respond adequately to any of the three incidents and two students of color have become less participatory. Design your response plan: the private conversations you have with the affected students (write the opening for each conversation — 2-3 sentences), the classroom community repair activity you design for the following week (not a lecture — a structured activity that allows students to name and process the dynamic), the new classroom discussion protocol you establish that gives students of color more control over when and how they engage with identity-related content, your own professional learning commitment (3 specific resources you will engage with), and the conversation you have with your instructional coach or principal about what happened. Write the repair activity plan in detail.","tags":["sel","equity","microaggressions","high-school","classroom-culture"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-88","title":"Math Test Anxiety Reduction Plan for 7th Grade","prompt":"You are a middle school math teacher whose 7th-grade class of 30 students shows dramatic performance drops on tests compared to homework and classwork — your analysis suggests that at least 10 students likely have significant math test anxiety. Design a comprehensive test anxiety reduction plan embedded in your math class: the classroom environment changes you make on test days (specify 5 sensory and procedural changes), a 3-minute pre-test breathing and grounding routine you teach in the first week and use before every assessment, 3 low-stakes assessment formats you introduce early in the year to normalize evaluation and build confidence before high-stakes tests, a test-taking strategy mini-lesson covering the 4 specific strategies students use when they encounter a problem they do not know how to solve (write out the 4 strategies), a post-test reflection students complete regardless of score (provide the 5-question reflection form), and the individual support plan you create for the 3 students with the most severe anxiety including how you communicate with their parents and the school counselor. Include the script for introducing test anxiety openly to the whole class.","tags":["sel","test-anxiety","math","middle-school","assessment"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-89","title":"SEL Micro-Practices for High School Content Teachers","prompt":"You are a high school instructional coach working with a 9-teacher team to integrate SEL into daily content instruction without taking time away from academic content. The teachers have been trained in CASEL competencies but feel that SEL is an add-on to their real job. Design a whole-school content-SEL integration framework: 5 specific micro-practices that take under 3 minutes and can be embedded in any content class (describe each practice with an example from science, math, history, English, and PE), a structured academic controversy discussion protocol that simultaneously builds social awareness and academic discourse, a collaborative learning structure that explicitly develops relationship skills as a learning objective alongside the content objective, a student goal-setting routine at the start of each unit that connects academic goals to personal growth goals, and a teacher self-reflection tool used at the end of each week (5 questions, takes 5 minutes) that tracks whether the teacher created conditions for the SEL micro-practices. Write the training agenda for the 90-minute faculty session introducing this framework to the 9-teacher team.","tags":["sel","integration","high-school","instructional-coaching","casel"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-90","title":"Supporting a 4th-Grade Community Through Grief and Loss","prompt":"You are a 4th-grade teacher whose classroom community has been affected by two significant losses this school year: one student lost a parent to illness in October, and in January a beloved custodian who was close to the students passed away suddenly. Your class of 24 students is struggling and you are navigating your own grief as well. Design a developmentally appropriate classroom grief support plan: the immediate classroom response for the days following the custodian's death including what you say to the class (write the opening of the conversation), the range of reactions you can expect from 9-10 year olds and how you respond to each type, 3 classroom activities over the following 2 weeks that allow students to express and process grief in low-pressure ways, how you create a memorial or acknowledgment that honors the custodian and involves student agency, the ongoing support for the student who lost a parent (a separate, longer-term approach), and how you take care of yourself as the teacher — the specific support you seek and the boundaries you maintain with students about your own emotional state. Include the communication you send to families.","tags":["sel","grief","elementary","community","trauma-informed"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  // --- 10. PROFESSIONAL DEVELOPMENT (91-100) ---
  {"id":"edu-91","title":"6-Week Instructional Coaching Cycle for Math Discourse","prompt":"You are an instructional coach at a Title I middle school assigned to support 8 teachers in improving student discourse in math classrooms. Your principal wants to see measurable growth in student talk time, which currently averages 18% of class time in the 8 classrooms you support. Design a complete 6-week coaching cycle for one of your teachers — a 7th-grade math teacher with 15 years of experience who is resistant to feedback but cares deeply about her students. Include: the pre-observation meeting protocol (what you ask, what you listen for, how you set a focused observation lens together — 20 minutes), the observation data collection tool you use focused specifically on student discourse (not general checklists — describe the specific data you collect and how), the post-observation conference protocol using data from your observation to drive a teacher-led analysis (write the 4 questions you ask, in order), the agreed-upon goal statement and the 2 specific instructional strategies the teacher will try in the next 2 weeks, and the Week 6 re-observation analysis showing what changed. Include how you navigate the resistance without damaging the relationship.","tags":["professional-development","instructional-coaching","math","discourse","middle-school"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"edu-92","title":"Comprehensive New Teacher Induction Program for a District","prompt":"You are a Director of Curriculum and Instruction at a mid-size district that historically loses 40% of new teachers before their third year. Your new teacher induction program currently consists of a 3-day orientation in August and monthly check-ins with HR. Design a comprehensive, research-informed new teacher induction program for Year 1 and Year 2 teachers: a 3-day August orientation agenda that prioritizes practical survival skills and relationship-building over policy review (provide a detailed Day 1 schedule in 30-minute blocks), a monthly new teacher PD calendar for the full school year with the topic, format, and duration of each session, a mentor teacher pairing protocol specifying how mentors are selected, trained, and compensated (include the 3 non-negotiables for mentor selection), a classroom observation protocol mentors use in the first 8 weeks focused on support not evaluation, a mid-year retention survey (provide the 12 questions) to identify at-risk teachers before they resign, and the Year 2 program that transitions from survival to growth. Include the budget estimate per new teacher for the program.","tags":["professional-development","new-teacher","induction","district","retention"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-93","title":"PLC Reset and Re-Launch for a High School English Department","prompt":"You are a high school English department chair facilitating a Professional Learning Community with 6 English teachers who meet every Tuesday for 50 minutes. The PLC has been running for 2 years but has stagnated — meetings feel like reporting sessions rather than collaborative learning, and instructional practices in classrooms have not meaningfully changed. Design a PLC reset and re-launch plan: the 1-hour PLC reset session you facilitate in September using a team self-assessment protocol (provide the 8-question team health survey), the new meeting structure for the school year with a timed agenda template (5-min check-in, 10-min data review, 20-min collaborative work, 10-min planning next steps, 5-min debrief), a semester-long inquiry cycle structure focused on one shared instructional challenge (the team identifies the challenge in session 2 — describe the facilitation process), the norms of collaboration you co-create with the team and the accountability mechanism for when norms are violated, and how you document and share PLC learning with the wider faculty. Include the specific facilitation moves for managing the dominant personality who tends to shut down productive disagreement.","tags":["professional-development","plc","department-leadership","high-school","collaboration"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-94","title":"Redesigning Teacher Observation and Evaluation for Growth","prompt":"You are a high school principal redesigning your teacher observation and evaluation system to be growth-focused rather than compliance-driven. Your current system requires 2 formal observations per year with a checklist rubric, and teachers report that it feels punitive and disconnected from their actual practice. Design a new observation and evaluation model for your 45-teacher faculty: a 3-tier system that differentiates the observation experience for tenured strong performers, teachers needing support, and new teachers, the informal learning walk protocol you use 3 times per year with all teachers (describe what you look for, how long you stay, what you say afterward), the pre-observation conference form that makes the teacher an active agent in what you observe (5 questions), a post-observation feedback protocol that guarantees one specific, positive observation and one prioritized growth area with a concrete next step, the summative evaluation rubric for the formal end-of-year review (4 domains, 4 levels each — provide the 4 domain names and brief descriptors), and how you handle the teacher whose performance is persistently unsatisfactory.","tags":["professional-development","teacher-evaluation","principal","leadership","observation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-95","title":"6-Month Equity Audit of K-5 Social Studies Curriculum","prompt":"You are a curriculum coordinator leading a district-wide equity audit of K-5 social studies curriculum materials. Your district has a majority-minority student population and preliminary data suggests that the current curriculum materials feature primarily white male historical figures and Eurocentric perspectives. Design the complete equity audit process for a 6-month review: the audit team composition and the case for including community members and student voices alongside teachers and administrators, the 4-dimension audit framework you use to evaluate each unit and resource (representation, power and agency, accuracy about historical harm, and connection to present-day relevance — provide the 5 evaluation criteria for each dimension), the review protocol teams use for analyzing a curriculum unit (what they look for, how they document findings, and how long it takes), the data summary process for presenting findings to the school board, the 3-year curriculum revision plan that comes out of the audit, and how you communicate transparently with families about what the audit found and what changes are coming.","tags":["professional-development","equity","curriculum","district","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-96","title":"12-Week Coaching Plan for a Struggling Veteran Math Teacher","prompt":"You are an instructional coach who has been assigned to support a 22-year veteran 8th-grade math teacher whose students consistently underperform on state assessments and who has received two unsatisfactory ratings in the past 3 years. The teacher is deeply demoralized, believes the problem is the students' home situations, and has disengaged from professional development. Your principal has framed this as a final support attempt before an improvement plan. Design your coaching approach: the trust-building strategy for the first 4 weeks before any instructional feedback occurs (specify 3 concrete relationship-building moves), the diagnostic process for understanding what is actually happening instructionally (which data you look at, what you observe in the classroom, and how you structure a non-threatening initial conversation), your theory of change for this teacher — the one instructional lever you choose to focus on and why, a 12-week coaching plan with weekly focus areas and milestones, how you simultaneously manage your obligation to the principal who is watching for improvement, and the decision point at Week 8 where you assess whether the coaching is working. Include the conversation you have at Week 8 when there has been minimal change.","tags":["professional-development","instructional-coaching","veteran-teacher","support","leadership"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-97","title":"Full-Day Culturally Responsive Teaching Workshop for Faculty","prompt":"You are a professional development facilitator designing a full-day (6-hour) culturally responsive teaching (CRT) workshop for a faculty of 55 teachers at a high school where 72% of students are students of color and 85% of teachers are white. Previous diversity trainings have been described as guilt trips by some teachers and have not changed practice. Design the workshop: an opening activity that builds psychological safety and establishes the purpose as improving student outcomes (describe the activity and your facilitation moves), a structured self-reflection protocol teachers complete on their own curriculum and teaching in the first 2 hours, a video case study analysis of CRT in practice (describe the video you show and the 4 discussion questions), a practical classroom application work session in the afternoon where teachers redesign one upcoming lesson using 3 CRT principles (specify the 3 principles and the redesign protocol), a closing commitment activity, and the 30-day follow-up structure that connects the workshop to classroom practice. Include your preparation for the most common forms of resistance you will encounter.","tags":["professional-development","culturally-responsive","faculty","equity","training"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-98","title":"2-Year Teacher Leadership Pipeline Development Program","prompt":"You are an assistant principal at a K-8 school who has identified 6 teachers with strong leadership potential. You want to develop them into formal and informal leaders without losing them to administration or other schools. Design a 2-year teacher leadership development program: Year 1 focus areas and monthly activities (specify an activity for each month — these might be facilitated readings, shadow experiences, leading professional development, or action research projects), the formal teacher leadership roles that exist or you will create in the school (specify 4 roles with titles, responsibilities, and compensation or load reduction), the mentoring relationship between each teacher leader and you as their developer (describe the monthly 1:1 structure and what it is not — not just a check-in), the action research project each teacher completes in Year 2 and how findings are presented to faculty, and how you retain these teachers when neighboring schools or the district office recruit them away. Include the conversation you have with each of the 6 teachers when you invite them into the program.","tags":["professional-development","teacher-leadership","school-leadership","pipeline","retention"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-99","title":"School-Wide Teacher Wellbeing Initiative to Reduce Burnout","prompt":"You are a principal at a Title I elementary school where teacher turnover reached 35% last year and exit interviews cited burnout, workload, and lack of support as the primary reasons. You cannot significantly raise salaries but you can change the working conditions. Design a comprehensive teacher wellbeing initiative: a workload audit process where you identify 5 tasks teachers currently do that you will eliminate, reduce, or redistribute (name plausible specific tasks), a meeting audit resulting in a meeting calendar where every meeting has a clear purpose and no meeting runs over 45 minutes, a peer support structure (not mandated by admin) that builds collegial relationships — specify the structure, how it starts, and how you protect it from becoming administrative, a classroom coverage protocol that guarantees every teacher 3 uninterrupted 30-minute breaks per week outside of lunch and prep, a monthly temperature check survey (provide the 8 questions) that you use to identify early signs of burnout and respond quickly, and a transparent communication plan where you share what you are doing to address workload concerns and admit what you cannot fix. Include the 3 things you will stop doing as a principal to model sustainable practice.","tags":["professional-development","teacher-wellbeing","burnout","school-leadership","retention"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"edu-100","title":"School Improvement Planning for an Academic Watch List Middle School","prompt":"You are a principal at a middle school that has been on your state's academic watch list for 3 consecutive years due to low math and ELA proficiency rates, particularly among Black and Latino students. Your school has 420 students and 28 teachers, a new district superintendent who is watching closely, and a school community that has experienced rapid leadership turnover. You have 2 years to demonstrate meaningful improvement or face state intervention. Design a rigorous school improvement planning process: a 6-week stakeholder engagement process that includes students, teachers, families, and community members and produces a root cause analysis (describe the 3 community sessions, who facilitates each, and how data is used to ground the conversation), the structure of the School Improvement Plan document itself (specify the 5 sections, what data goes in each, and who is responsible), the 3 priority goals you will likely identify based on typical watch-list school patterns (provide plausible specific goals with measurable targets), the quarterly progress monitoring process including who reviews what data and how mid-year corrections happen, and how you maintain community trust and teacher morale during a period of intense external scrutiny. Include the 10-minute weekly leadership team check-in protocol.\n\n[Describe your classroom situation]","tags":["professional-development","school-improvement","principal","leadership","strategic-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false}

];
  __exports.educationPrompts = educationPrompts;
})();